211	      if (channel.kind === "collect") apply("contest-collect", startCollect, { playerId, sourceId: channel.sourceId, tick: now });
212	      else apply("contest-claim", startCacheClaim, { playerId, cacheId: channel.cacheId, rubbingId: channel.rubbingId, tick: now });
213	    }],
214	    [4, () => {
215	      if (players().length < 2) return;
