400	  ["repeated request id replayed", ["purchase-replayed"]],
401	  ["request id reused for another purchase", ["rebuy:duplicate"]],
402	  ["short gold", ["buy-rumor:insufficient-gold", "buy-tonic:insufficient-gold"]],
403	  ["third tonic", ["buy-tonic:tonic-limit"]],
404	  ["purchase in a duel", ["buy-rumor:player-in-duel", "buy-tonic:player-in-duel"]],
405	  ["purchase while disconnected", ["buy-rumor:player-disconnected", "buy-tonic:player-disconnected"]],
406	  ["purchase after leaving", ["buy-rumor:player-left", "buy-tonic:player-left"]],
407	  ["tonic used", ["use-tonic:ok"]],
