409	  ["second tonic while active", ["use-tonic:tonic-active"]],
410	  ["no tonic carried", ["use-tonic:no-tonic"]],
411	  ["tonic off the sea", ["use-tonic:not-at-sea"]],
412	  ["tonic while grappled", ["use-tonic:grappled"]],
413	  ["tonic in a duel", ["use-tonic:player-in-duel"]],
414	  ["tonic after leaving", ["use-tonic:player-left"]],
415	];
