417	describe("ledger property: no rubbing is ever lost or duplicated (§19)", () => {
418	  for (const preset of ["slice", "alpha"] as const) {
419	    it(`keeps the invariant after every step of ${SEEDS.length} random ${preset} matches and replays them identically`, { timeout: 120_000 }, () => {
420	      const totals: Stats = {};
421	      for (const seed of SEEDS) {
422	        const first = simulate(preset, seed, STEPS);
423	        // The replay skips the per-step checks, which draw nothing from the dice, so it is the same sequence.
424	        const again = simulate(preset, seed, STEPS, false);
425	        expect(hashState(again.state)).toBe(hashState(first.state));
426	        expect(again.stats).toEqual(first.stats);
427	        expect(first.stats.operations).toBeGreaterThan(2000);
428	        for (const [key, value] of Object.entries(first.stats)) totals[key] = (totals[key] ?? 0) + value;
