430	      // The invariant was not checked vacuously: every rule the sequences are meant to exercise happened.
431	      const missing = EXERCISED.filter(([, keys]) => keys.every((key) => (totals[key] ?? 0) === 0)).map(([rule]) => rule);
432	      expect(missing).toEqual([]);
433	    });
434	  }
435	
436	  it("replays to a different state from a different seed", { timeout: 60_000 }, () => {
